"""Fail-closed validation for a future, separately reviewed 216-fork run.

This module is deliberately inert: it reads and hashes files only. It never
launches a process, probes host state, generates bindings, or creates approval.

Expected frozen input shapes (all paths in bindings are absolute; evidence and
source-manifest paths are kit-relative):

* ``SOURCE_FILES.json``: ``{"schema": 1, "files": {relative_path: sha256}}``.
  It must name every top-level .py/.java/.c file, README.md,
  OFFLINE_VALIDATION.json, and the frozen proposal and schedule. The manifest
  itself, mutable bindings, launch review, and outputs are excluded to avoid
  circular hashes.
* ``EXECUTION_BINDINGS.json``: schema 1, exact baseline/candidate pins, a
  verified CPU, ``paths`` (base/template java, classes directory, native .so),
  ``images`` (base/template roots, clean source commit, complete tree
  manifest, modules hash, CDS-file hashes, native-file hashes, build identity),
  and ``evidence`` receipts. Tree manifests map relative names to either
  ``{"type":"file","sha256":...}`` or
  ``{"type":"symlink","target":...}``.
* Evidence receipt records in bindings have ``path`` and ``sha256``. The
  candidate correctness/linkage, host admission, and both build receipts are
  JSON files whose fields are checked below. Six compiler-diagnostic records
  cover three caller cells on each of the base and template images, and assert
  pre-warm root evidence. They are attestations to be reviewed and pinned, not
  generated by this validator.
* ``LAUNCH_REVIEW.json`` must record a separate human execution grant with
  ``authorized: true``, a nonempty authorization id and reviewer, and exact
  hashes of bindings, proposal, schedule, and source manifest. The grant may
  authorize freezing real runtime artifacts under the reviewed binding procedure;
  it does not imply that the human independently inspected each later artifact.
  This module cannot create approval or that record.

The exact field names are intentionally documented here so preparation can
produce concrete receipts without weakening validation at launch time.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import stat
from pathlib import Path, PurePosixPath

import accounting_contract
import budget
import decision


SCHEMA = 1
BASE = "02324e6bd026411407983df06284cd79460c33f6"
CANDIDATE = "b67cf2421d5dca1df4d9759003e1983a1b810f86"
TEMPLATE_PAYLOAD_SHA256 = "ccffb3898eb9adfbdd22912989a46859247c05bc65c32b89624f103d3e4d5d34"
TEMPLATE_PAYLOAD_LENGTH = 1314
TEMPLATE_ENTRY_COUNT = 2
TEMPLATE_PAYLOAD_CRC32 = 1243521826
FROZEN_FILES = ("EXECUTION_BINDINGS.json", "PROPOSAL.json", "SCHEDULE.json",
                "SOURCE_FILES.json")
SOURCE_SUFFIXES = {".py", ".java", ".c"}
DIAGNOSTIC_CELLS = {"c2-unbound": ("callsUnbound", 4),
                    "c2-bound": ("callsBound", 4),
                    "c1-unbound": ("callsUnbound", 1)}
DIAGNOSTIC_PAIRS = {(image, cell) for image in ("base", "template")
                    for cell in DIAGNOSTIC_CELLS}
HEX = re.compile(r"^[0-9a-f]{64}$")


def _need(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def _json(path: Path, expected_type=dict):
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"cannot read JSON input {path}: {exc}") from exc
    _need(type(value) is expected_type,
          f"JSON {expected_type.__name__} required: {path}")
    return value


def _hash_file(path: Path) -> str:
    _need(path.is_file(), f"not a regular file: {path}")
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while True:
            chunk = stream.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def _hex(value, label: str) -> str:
    _need(type(value) is str and HEX.fullmatch(value) is not None,
          f"invalid sha256: {label}")
    return value


def _cgroup_ancestor_chain(leaf: str, mountpoint: str) -> list[str]:
    """Return absolute cgroup directories leaf-to-mount-root, validating scope."""
    _need(type(leaf) is str and type(mountpoint) is str,
          "cgroup leaf and mountpoint paths are required")
    leaf_path, root_path = PurePosixPath(leaf), PurePosixPath(mountpoint)
    _need(leaf_path.is_absolute() and root_path.is_absolute()
          and ".." not in leaf_path.parts and ".." not in root_path.parts,
          "invalid cgroup path scope")
    try:
        leaf_path.relative_to(root_path)
    except ValueError as exc:
        raise ValueError("cgroup leaf is outside visible mount root") from exc
    chain = []
    current = leaf_path
    while True:
        chain.append(str(current))
        if current == root_path:
            break
        current = current.parent
    return chain


def _validate_cgroup_limits(value, leaf: str, mountpoint: str) -> dict:
    _need(type(value) is dict, "complete cgroup ancestor limit receipt required")
    chain = _cgroup_ancestor_chain(leaf, mountpoint)
    _need(set(value) == set(chain),
          "cgroup limit receipt must cover the complete leaf-to-mount-root chain")
    normalized = {}
    for directory in chain:
        limits = value[directory]
        _need(type(limits) is dict
              and set(limits) == {"cpu.max", "cpuset.cpus.effective"},
              f"cpu.max and cpuset.cpus.effective required at {directory}")
        for name, content in limits.items():
            _need(content is None or (type(content) is str and content == content.strip()),
                  f"noncanonical cgroup limit value at {directory}/{name}")
        normalized[directory] = dict(limits)
    return normalized


def _read_cgroup_limits(chain: list[str]) -> dict:
    result = {}
    for directory in chain:
        result[directory] = {}
        for name in ("cpu.max", "cpuset.cpus.effective"):
            try:
                value = (Path(directory) / name).read_text(encoding="ascii").strip()
            except FileNotFoundError:
                value = None
            except (OSError, UnicodeError) as exc:
                raise ValueError(f"cannot read cgroup limit {directory}/{name}: {exc}") from exc
            result[directory][name] = value
    return result


def _safe_relative(value: str) -> PurePosixPath:
    _need(type(value) is str and value and "\\" not in value and "\x00" not in value,
          "invalid relative path")
    path = PurePosixPath(value)
    _need(not path.is_absolute() and str(path) == value
          and all(part not in ("", ".", "..") for part in path.parts),
          "unsafe relative path")
    return path


def _inside(root: Path, relative: str) -> Path:
    rel = _safe_relative(relative)
    path = root.joinpath(*rel.parts)
    resolved = path.resolve(strict=True)
    _need(resolved == root or root in resolved.parents, f"path escapes image/kit root: {relative}")
    return path


def _inventory(root: Path) -> dict[str, dict[str, str]]:
    """Return a complete deterministic file/symlink inventory; reject special files."""
    root = root.resolve(strict=True)
    _need(root.is_dir(), f"tree root is not a directory: {root}")
    result = {}
    stack = [root]
    while stack:
        directory = stack.pop()
        for entry in sorted(os.scandir(directory), key=lambda item: item.name):
            path = Path(entry.path)
            relative = path.relative_to(root).as_posix()
            mode = entry.stat(follow_symlinks=False).st_mode
            if stat.S_ISLNK(mode):
                target = os.readlink(path)
                resolved = path.resolve(strict=True)
                _need(resolved == root or root in resolved.parents,
                      f"symlink escapes tree: {relative}")
                result[relative] = {"type": "symlink", "target": target}
            elif stat.S_ISDIR(mode):
                stack.append(path)
            elif stat.S_ISREG(mode):
                result[relative] = {"type": "file", "sha256": _hash_file(path)}
            else:
                raise ValueError(f"unsupported special file in tree: {relative}")
    return dict(sorted(result.items()))


def _tree_hash(manifest: dict[str, dict[str, str]]) -> str:
    encoded = json.dumps(manifest, sort_keys=True, separators=(",", ":"),
                         ensure_ascii=True).encode("ascii")
    return hashlib.sha256(encoded).hexdigest()


def _path_fingerprint(path: Path) -> str:
    if path.is_symlink():
        target = os.readlink(path).encode("utf-8", errors="surrogateescape")
        return hashlib.sha256(b"SYMLINK\0" + target).hexdigest()
    return _hash_file(path)


def _add_tree_fingerprints(fingerprints: dict[str, str], root: Path,
                           manifest: dict[str, dict[str, str]]) -> None:
    root = root.resolve(strict=True)
    actual = _inventory(root)
    _need(actual == manifest, f"tree manifest differs from disk: {root}")
    fingerprints["tree:" + str(root)] = _tree_hash(actual)
    for relative in actual:
        path = root.joinpath(*_safe_relative(relative).parts)
        fingerprints[str(path)] = _path_fingerprint(path)


def _receipt(root: Path, value, label: str, fingerprints: dict[str, str]) -> dict:
    _need(type(value) is dict, f"missing evidence receipt: {label}")
    relative = value.get("path")
    expected = _hex(value.get("sha256"), label)
    path = _inside(root, relative)
    actual = _hash_file(path)
    _need(actual == expected, f"evidence hash mismatch: {label}")
    fingerprints[str(path.resolve(strict=True))] = actual
    return _json(path)


def _validate_source_manifest(root: Path, fingerprints: dict[str, str]) -> None:
    manifest_path = root / "SOURCE_FILES.json"
    manifest = _json(manifest_path)
    _need(manifest.get("schema") == SCHEMA and type(manifest.get("files")) is dict,
          "invalid source manifest")
    listed = manifest["files"]
    actual_sources = {path.name for path in root.iterdir()
                      if path.is_file() and path.suffix in SOURCE_SUFFIXES}
    required = actual_sources | {"PROPOSAL.json", "SCHEDULE.json", "README.md", "RUNBOOK.md",
                                 "OFFLINE_VALIDATION.json"}
    _need(set(listed) == required,
          "SOURCE_FILES.json must cover all harness sources, proposal and schedule")
    for name, expected in sorted(listed.items()):
        rel = _safe_relative(name)
        _need(len(rel.parts) == 1, "source manifest paths must be top-level")
        path = root / name
        actual = _hash_file(path)
        _need(actual == _hex(expected, name), f"source hash mismatch: {name}")
        fingerprints[str(path.resolve(strict=True))] = actual
    fingerprints[str(manifest_path.resolve(strict=True))] = _hash_file(manifest_path)


def _validate_proposal(root: Path, fingerprints: dict[str, str]) -> dict:
    proposal_path = root / "PROPOSAL.json"
    proposal = _json(proposal_path)
    for key, expected in decision.PLAN.items():
        _need(proposal.get(key) == expected, f"proposal differs from frozen decision: {key}")
    _need(proposal.get("baseline") == BASE and proposal.get("candidate") == CANDIDATE,
          "source pins changed")
    fingerprints[str(proposal_path.resolve(strict=True))] = _hash_file(proposal_path)
    return proposal


def _validate_schedule(root: Path, fingerprints: dict[str, str]) -> None:
    schedule_path = root / "SCHEDULE.json"
    schedule = _json(schedule_path, list)
    decision.validate_schedule(schedule)
    _need(schedule == decision.make_schedule(), "schedule is not the frozen randomized schedule")
    fingerprints[str(schedule_path.resolve(strict=True))] = _hash_file(schedule_path)


def _validate_image(root: Path, name: str, image: dict,
                    fingerprints: dict[str, str]) -> dict:
    _need(type(image) is dict, f"missing image record: {name}")
    source_commit = BASE if name == "base" else CANDIDATE
    _need(image.get("source_commit") == source_commit and image.get("source_clean") is True,
          f"wrong/dirty source identity for {name}")
    image_root_value = image.get("root")
    _need(type(image_root_value) is str and os.path.isabs(image_root_value),
          f"absolute image root required: {name}")
    image_root = Path(image_root_value).resolve(strict=True)
    _need(image_root.is_dir(), f"image root missing: {name}")
    manifest = image.get("tree_manifest")
    _need(type(manifest) is dict and bool(manifest), f"complete image tree manifest required: {name}")
    for relative, entry in manifest.items():
        _safe_relative(relative)
        _need(type(entry) is dict, f"invalid tree entry: {relative}")
        if entry.get("type") == "file":
            _hex(entry.get("sha256"), relative)
        elif entry.get("type") == "symlink":
            _need(type(entry.get("target")) is str and entry["target"],
                  f"invalid symlink target: {relative}")
        else:
            raise ValueError(f"invalid tree entry type: {relative}")
    _add_tree_fingerprints(fingerprints, image_root, manifest)
    tree_hash = _tree_hash(manifest)
    _need(image.get("tree_sha256") == tree_hash, f"image tree hash mismatch: {name}")

    modules = _inside(image_root, "lib/modules")
    modules_hash = _hash_file(modules)
    _need(image.get("modules_sha256") == modules_hash, f"module image hash mismatch: {name}")

    cds_files = image.get("cds_files")
    _need(type(cds_files) is dict and bool(cds_files), f"per-image CDS files required: {name}")
    actual_cds = {}
    for relative, expected in sorted(cds_files.items()):
        _safe_relative(relative)
        _need(relative.startswith("lib/server/") and relative.endswith(".jsa"),
              f"unexpected CDS path: {relative}")
        file = _inside(image_root, relative)
        actual = _hash_file(file)
        _need(actual == _hex(expected, relative), f"CDS hash mismatch: {name}/{relative}")
        actual_cds[relative] = actual
        fingerprints[str(file.resolve(strict=True))] = actual
    cds_hash = _tree_hash({k: {"type": "file", "sha256": v}
                           for k, v in sorted(actual_cds.items())})
    _need(image.get("cds_sha256") == cds_hash, f"CDS aggregate hash mismatch: {name}")

    native = image.get("native_files")
    _need(type(native) is dict and bool(native), f"native file hashes required: {name}")
    expected_native_paths = {
        relative for relative in manifest
        if relative.rsplit("/", 1)[-1].endswith(".so")
        or ".so." in relative.rsplit("/", 1)[-1]
    }
    _need(set(native) == expected_native_paths,
          f"native file inventory is incomplete: {name}")
    for relative, expected in sorted(native.items()):
        _safe_relative(relative)
        _need(relative.startswith("lib/") and relative not in ("lib/modules",),
              f"invalid native path: {relative}")
        file = _inside(image_root, relative)
        actual = _hash_file(file)
        _need(actual == _hex(expected, f"{name}/{relative}"),
              f"native hash mismatch: {name}/{relative}")
        fingerprints[str(file.resolve(strict=True))] = actual

    build = image.get("build_identity")
    _need(type(build) is dict, f"build identity missing: {name}")
    _need(build.get("target") == "Linux/aarch64"
          and build.get("profile") == "configure-dev"
          and build.get("debug_level") == "release"
          and build.get("ccache_enabled") is False,
          f"unexpected build profile: {name}")
    for key in ("configure_sha256", "configure_args_sha256", "boot_jdk_sha256",
                "gcc_sha256", "mold_sha256"):
        _hex(build.get(key), f"{name}.build_identity.{key}")
    build_receipt = _receipt(root, image.get("build_receipt"), f"{name} build", fingerprints)
    _need(build_receipt.get("status") == "PASS"
          and build_receipt.get("source_commit") == source_commit
          and build_receipt.get("tree_sha256") == tree_hash
          and build_receipt.get("build_identity") == build,
          f"build receipt does not bind image/build identity: {name}")
    generated = None
    if name == "template":
        generated = image.get("generated_template")
        _need(type(generated) is dict, "candidate generated-template identity missing")
        _hex(generated.get("source_id"), "candidate generated-template source id")
        _need(generated.get("payload_sha256") == TEMPLATE_PAYLOAD_SHA256
              and generated.get("length") == TEMPLATE_PAYLOAD_LENGTH
              and generated.get("entries") == TEMPLATE_ENTRY_COUNT
              and generated.get("crc32") == TEMPLATE_PAYLOAD_CRC32,
              "candidate generated-template payload identity mismatch")
        _hex(generated.get("metadata_sha256"), "candidate generated metadata")
        _hex(generated.get("resource_sha256"), "candidate generated resource")
    return dict(root=image_root, tree_sha256=tree_hash, modules_sha256=modules_hash,
                cds_sha256=cds_hash, cds_files=actual_cds, native_files=dict(native),
                build_identity=build, generated_template=generated)


def _validate_evidence(root: Path, bindings: dict, images: dict,
                       fingerprints: dict[str, str]) -> None:
    evidence = bindings.get("evidence")
    _need(type(evidence) is dict, "evidence receipt set missing")

    correctness = _receipt(root, evidence.get("candidate_correctness"),
                           "candidate correctness", fingerprints)
    candidate_tree = images["template"]["tree_sha256"]
    _need(correctness.get("status") == "PASS"
          and correctness.get("candidate_commit") == CANDIDATE
          and correctness.get("candidate_tree_sha256") == candidate_tree
          and correctness.get("platform") == "Linux/aarch64"
          and correctness.get("required_mode") == {
              "status": "PASS", "selected": True, "platform": "linux-aarch64"},
          "accepted ARM64 correctness must bind selected template to candidate image")

    linkage = _receipt(root, evidence.get("candidate_image_linkage"),
                       "candidate source/image linkage", fingerprints)
    _need(linkage.get("status") == "PASS"
          and linkage.get("source_commit") == CANDIDATE
          and linkage.get("tree_sha256") == candidate_tree
          and linkage.get("modules_sha256") == images["template"]["modules_sha256"],
          "candidate source/image linkage does not match frozen image")
    _need(linkage.get("generated_template") == images["template"]["generated_template"],
          "candidate linkage does not bind generated payload, metadata, and source id")

    host = _receipt(root, evidence.get("host_admission"), "host admission", fingerprints)
    cpu = bindings.get("cpu")
    _need(type(cpu) is int and cpu >= 0, "frozen admitted CPU required")
    _need(host.get("status") == "PASS" and host.get("platform") == "Linux/aarch64"
          and host.get("execution_environment") == "native-linux-vm"
          and host.get("cpu") == cpu
          and host.get("collector_and_java_same_pid_namespace") is True
          and host.get("collector_and_java_same_cgroup") is True
          and host.get("wait4_individual_child_cpu") is True
          and host.get("cpu_in_affinity_and_cpuset") is True
          and host.get("child_membership_verified") is True
          and host.get("child_affinity_verified") is True
          and host.get("proc_cpu_mapping_verified") is True
          and host.get("accounting_scope_verified") is True
          and type(host.get("affinity_cpus")) is list and cpu in host["affinity_cpus"]
          and type(host.get("cpuset_cpus")) is list and cpu in host["cpuset_cpus"]
          and host.get("no_concurrent_build_test_or_input_write") is True
          and type(host.get("boot_id")) is str and bool(host["boot_id"]),
          "actual Linux VM/CPU/wait4 admission does not match bindings")
    for key in ("namespace_id", "cgroup_path", "collector_pid", "witness_child_pid"):
        value = host.get(key)
        _need(value not in (None, "", 0), f"host admission lacks {key}")
    _validate_cgroup_limits(host.get("cgroup_limits"), host["cgroup_path"],
                            host.get("cgroup_mountpoint"))

    overall_budget = _receipt(root, evidence.get("overall_budget"),
                               "overall campaign budget", fingerprints)
    checked_budget = budget.validate_budget(overall_budget)
    _need(checked_budget["boot_id"] == host["boot_id"],
          "overall budget and host admission must share the admitted boot id")

    native_path = Path(bindings["paths"]["native"]).resolve(strict=True)
    native_hash = _hash_file(native_path)
    native_build = _receipt(root, evidence.get("native_build"),
                            "native benchmark library build", fingerprints)
    native_source = root / "native.c"
    _need(native_build.get("status") == "PASS"
          and native_build.get("source_sha256") == _hash_file(native_source)
          and native_build.get("library_sha256") == native_hash
          and native_build.get("compiler_sha256") == images["base"]["build_identity"]["gcc_sha256"]
          and images["template"]["build_identity"]["gcc_sha256"]
          == native_build.get("compiler_sha256")
          and type(native_build.get("command")) is str and native_build["command"].strip(),
          "native library receipt must bind native.c, artifact and matched GCC")

    diagnostics = evidence.get("compiler_diagnostics")
    _need(type(diagnostics) is list and len(diagnostics) == 6,
          "exactly six actual compiler-root diagnostics are required")
    seen = set()
    for index, record in enumerate(diagnostics):
        diagnostic = _receipt(root, record, f"compiler diagnostic {index + 1}", fingerprints)
        pair = (diagnostic.get("image"), diagnostic.get("cell"))
        _need(pair in DIAGNOSTIC_PAIRS and pair not in seen,
              "diagnostics must cover both images and three selected callers exactly once")
        seen.add(pair)
        caller, level = DIAGNOSTIC_CELLS[pair[1]]
        label_image = images[pair[0]]
        _need(diagnostic.get("status") == "PASS"
              and diagnostic.get("pre_warm_marker") is True
              and diagnostic.get("compiled_root_verified") is True
              and diagnostic.get("caller") == caller
              and diagnostic.get("compiler_level") == level
              and diagnostic.get("image_tree_sha256") == label_image["tree_sha256"]
              and type(diagnostic.get("root_evidence")) is str
              and bool(diagnostic["root_evidence"]),
              f"diagnostic is not actual pre-warm compiled-root evidence: {pair}")
    _need(seen == DIAGNOSTIC_PAIRS, "compiler diagnostic coverage incomplete")


def _validate_launch_review(root: Path, bindings_path: Path, fingerprints: dict[str, str]) -> None:
    review_path = root / "LAUNCH_REVIEW.json"
    review = _json(review_path)
    _need(review.get("schema") == SCHEMA and review.get("authorized") is True,
          "separate launch review is not authorized")
    _need(type(review.get("authorization_id")) is str and review["authorization_id"].strip(),
          "launch review authorization id missing")
    _need(type(review.get("reviewer")) is str and review["reviewer"].strip()
          and review.get("reviewer_type") == "human",
          "human reviewer identity required; validation cannot auto-approve")
    expected = {
        "EXECUTION_BINDINGS.json": _hash_file(bindings_path),
        "PROPOSAL.json": _hash_file(root / "PROPOSAL.json"),
        "SCHEDULE.json": _hash_file(root / "SCHEDULE.json"),
        "SOURCE_FILES.json": _hash_file(root / "SOURCE_FILES.json"),
    }
    hashes = review.get("sha256")
    _need(hashes == expected, "launch review hashes do not bind exact frozen inputs")
    fingerprints[str(review_path.resolve(strict=True))] = _hash_file(review_path)


def validate_inputs(root: Path) -> tuple[dict, dict[str, str]]:
    """Validate reviewed prospective inputs and return bindings plus fingerprints."""
    root = Path(root).resolve(strict=True)
    _need(root.is_dir(), "input root must be a directory")
    fingerprints: dict[str, str] = {}
    _validate_source_manifest(root, fingerprints)
    _validate_proposal(root, fingerprints)
    _validate_schedule(root, fingerprints)

    bindings_path = root / "EXECUTION_BINDINGS.json"
    bindings = _json(bindings_path)
    _need(bindings.get("schema") == SCHEMA, "invalid execution bindings schema")
    _need(bindings.get("baseline") == BASE and bindings.get("candidate") == CANDIDATE,
          "execution source pins changed")
    _need(bindings.get("platform") == "Linux/aarch64" and bindings.get("release") is True,
          "execution must bind native Linux AArch64 release images")
    _need(type(bindings.get("cpu")) is int and bindings["cpu"] >= 0,
          "actual admitted CPU must be frozen")
    paths = bindings.get("paths")
    _need(type(paths) is dict, "runtime paths missing")
    images_value = bindings.get("images")
    _need(type(images_value) is dict and set(images_value) == {"base", "template"},
          "base and template images required")
    images = {name: _validate_image(root, name, images_value[name], fingerprints)
              for name in ("base", "template")}

    for name in ("base", "template"):
        expected = images[name]["root"] / "bin/java"
        value = paths.get(name)
        _need(type(value) is str and os.path.isabs(value)
              and Path(value) == expected,
              f"runtime path does not resolve to the frozen {name} image")
        java = Path(value)
        resolved_java = java.resolve(strict=True)
        _need(resolved_java.is_file()
              and (resolved_java == images[name]["root"]
                   or images[name]["root"] in resolved_java.parents)
              and os.access(java, os.X_OK), f"runtime executable unavailable: {name}")
        fingerprints[str(java)] = _path_fingerprint(java)

    _need(images["base"]["native_files"].keys() == images["template"]["native_files"].keys()
          and images["base"]["native_files"] == images["template"]["native_files"],
          "baseline/candidate native file sets or hashes differ")
    _need(images["base"]["modules_sha256"] != images["template"]["modules_sha256"],
          "base and candidate module images must remain separately identified")
    _need(images["base"]["build_identity"] == images["template"]["build_identity"],
          "baseline/candidate build configurations or toolchains differ")

    classes_value = paths.get("classes")
    _need(type(classes_value) is str and os.path.isabs(classes_value),
          "absolute benchmark classes directory required")
    classes_root = Path(classes_value).resolve(strict=True)
    classes_manifest = bindings.get("classes_tree_manifest")
    _need(type(classes_manifest) is dict and bool(classes_manifest),
          "complete benchmark classes tree manifest required")
    _need({"Probe.class", "Steady.class"}.issubset(classes_manifest),
          "benchmark class tree must include Probe.class and Steady.class")
    _add_tree_fingerprints(fingerprints, classes_root, classes_manifest)
    _need(_tree_hash(classes_manifest) == bindings.get("classes_tree_sha256"),
          "benchmark classes tree hash mismatch")

    native_value = paths.get("native")
    _need(type(native_value) is str and os.path.isabs(native_value),
          "absolute native benchmark library required")
    native_path = Path(native_value).resolve(strict=True)
    native_hash = _hash_file(native_path)
    _need(native_hash == _hex(bindings.get("native_sha256"), "native benchmark library"),
          "native benchmark library hash mismatch")
    fingerprints[str(native_path)] = native_hash

    _validate_evidence(root, bindings, images, fingerprints)
    fingerprints[str(bindings_path.resolve(strict=True))] = _hash_file(bindings_path)
    _validate_launch_review(root, bindings_path, fingerprints)
    return bindings, dict(sorted(fingerprints.items()))


def get_budget(root: Path, bindings: dict) -> dict:
    """Read and validate the frozen campaign budget receipt without host probes."""
    root = Path(root).resolve(strict=True)
    _need(type(bindings) is dict and type(bindings.get("evidence")) is dict,
          "validated bindings required for budget check")
    fingerprints: dict[str, str] = {}
    host = _receipt(root, bindings["evidence"].get("host_admission"),
                    "host admission", fingerprints)
    record = _receipt(root, bindings["evidence"].get("overall_budget"),
                      "overall campaign budget", fingerprints)
    checked = budget.validate_budget(record)
    _need(checked["boot_id"] == host.get("boot_id"),
          "overall budget and host admission must share the admitted boot id")
    return checked


def recheck_inputs(fingerprints: dict[str, str]) -> bool:
    """Re-hash files and complete trees captured by ``validate_inputs``."""
    _need(type(fingerprints) is dict and bool(fingerprints), "input fingerprints required")
    for key, expected in fingerprints.items():
        _hex(expected, key)
        if key.startswith("tree:"):
            root = Path(key[5:]).resolve(strict=True)
            actual = _tree_hash(_inventory(root))
        else:
            path = Path(key)
            actual = _path_fingerprint(path)
        _need(actual == expected, f"frozen input changed: {key}")
    return True


def validate_current_host(root: Path, bindings: dict,
                          proc_root: Path = Path("/proc")) -> dict:
    """Recheck admitted host identity before collector output creation.

    This is a read-only runtime precheck. Tests pass a temporary proc fixture;
    the campaign runner must call it on the admitted native Linux VM before
    creating output directories or launching children.
    """
    root = Path(root).resolve(strict=True)
    _need(type(bindings) is dict and type(bindings.get("evidence")) is dict,
          "validated bindings required for current-host check")
    fingerprints = {}
    host = _receipt(root, bindings["evidence"].get("host_admission"),
                    "host admission", fingerprints)
    cpu = bindings.get("cpu")
    _need(type(cpu) is int and cpu >= 0, "frozen admitted CPU required")

    boot_id = (proc_root / "sys/kernel/random/boot_id").read_text().strip()
    namespace_id = os.readlink(proc_root / "self/ns/pid")
    affinity = os.sched_getaffinity(0)
    _need(boot_id == host.get("boot_id"), "host boot id changed since admission")
    _need(namespace_id == host.get("namespace_id"), "PID namespace changed since admission")
    _need(cpu in affinity, "admitted CPU is no longer in collector affinity")

    membership = (proc_root / "self/cgroup").read_text()
    mountinfo = (proc_root / "self/mountinfo").read_text()
    candidate = accounting_contract.resolve_leaf_candidate(membership, mountinfo)
    direct = accounting_contract.verify_direct_membership(
        candidate, os.getpid(), (Path(candidate["path"]) / "cgroup.procs").read_text())
    _need(direct["path"] == host.get("cgroup_path"),
          "resolved direct cgroup differs from admitted collector cgroup")
    _need(candidate["mountpoint"] == host.get("cgroup_mountpoint"),
          "visible cgroup mount root differs from admission")
    chain = _cgroup_ancestor_chain(direct["path"], candidate["mountpoint"])
    admitted_limits = _validate_cgroup_limits(
        host.get("cgroup_limits"), direct["path"], candidate["mountpoint"])
    current_limits = _read_cgroup_limits(chain)
    _need(current_limits == admitted_limits,
          "cgroup cpu.max or cpuset.cpus.effective changed since admission")
    return {"boot_id": boot_id, "namespace_id": namespace_id,
            "cpu": cpu, "affinity_cpus": sorted(affinity),
            "cgroup_path": direct["path"], "membership_verified": True,
            "cgroup_limits": current_limits}
